CREATE TABLE ibexa_content_type_field_definition (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, status INTEGER DEFAULT 0 NOT NULL, can_translate INTEGER DEFAULT 1, category VARCHAR(25) DEFAULT '' NOT NULL, content_type_id INTEGER DEFAULT 0 NOT NULL, data_float1 DOUBLE PRECISION DEFAULT NULL, data_float2 DOUBLE PRECISION DEFAULT NULL, data_float3 DOUBLE PRECISION DEFAULT NULL, data_float4 DOUBLE PRECISION DEFAULT NULL, data_int1 INTEGER DEFAULT NULL, data_int2 INTEGER DEFAULT NULL, data_int3 INTEGER DEFAULT NULL, data_int4 INTEGER DEFAULT NULL, data_text1 VARCHAR(255) DEFAULT NULL, data_text2 VARCHAR(50) DEFAULT NULL, data_text3 VARCHAR(50) DEFAULT NULL, data_text4 VARCHAR(255) DEFAULT NULL, data_text5 CLOB DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '' NOT NULL, identifier VARCHAR(50) DEFAULT '' NOT NULL, is_information_collector INTEGER DEFAULT 0 NOT NULL, is_required INTEGER DEFAULT 0 NOT NULL, is_searchable INTEGER DEFAULT 0 NOT NULL, is_thumbnail BOOLEAN DEFAULT '0' NOT NULL, placement INTEGER DEFAULT 0 NOT NULL, serialized_data_text CLOB DEFAULT NULL, serialized_description_list CLOB DEFAULT NULL, serialized_name_list CLOB NOT NULL);
